input.command:
pmset -g log 2>/dev/null | awk '
/Charge:|Using Batt|Using AC| -InternalBattery|Sleep.*due to|Wake from|DarkWake|PreventUserIdleSystemSleep/ { print }
' | tail -120

echo "=== CUMULATIVE CPU ==="; ps -axo time,pcpu,pmem,rss,comm | sort -nr | head -30; echo "=== CHARGE TIMELINE ==="; pmset -g log 2>/dev/null | grep -E "Using (Batt|AC)\(Charge:" | awk '{
  ts=$1" "$2
  src=$0
  if (match(src, /Using (Batt|AC)\(Charge: [0-9]+\)/)) {
    print ts, substr(src, RSTART, RLENGTH)
  }
}' | awk '!seen[$0]++' | tail -80; echo "=== LOGIN ITEMS ==="; osascript -e 'tell application "System Events" to get the name of every login item' 2>/dev/null; echo "=== AUDIO ASSERTIONS NOW ==="; pmset -g assertions | grep -E "coreaudio|ToDesk|PreventUserIdle|pid " | head -40
